function regionColor(id){return id==='primary'?'#c34a64':id==='space_b'?'#9855c5':id==='space_d'?'#c87a14':'#0c8a66'}
function setRegionMeta(id,key,value){const b=regionBundle(),r=allRegions().find(x=>x.region_id===id);if(!r)return;if(id==='primary')b[key==='visible'?'primary_visible':'primary_observation_support']=value;else r[key]=value;}
function renderSpaceManager(){const list=allRegions();$('#spaceManager').innerHTML='<div class="spaceManagerHeader"><b>A/B坐标基线保留 · C/D空草稿不代表新参考</b><button id="newEmptySpace">新增空空间</button></div>'+list.map(r=>`<div class="spaceRow"><label><input type="checkbox" data-space-visible="${esc(r.region_id)}" ${r.visible!==false?'checked':''}> 显示 ${esc(r.name)}</label><button data-space-edit="${esc(r.region_id)}">独立编辑</button><span>${r.draft.polygon.length?r.draft.polygon.length+'个底面角点':'空草稿 · 未提供坐标'} · ${r.confirmed_version&&S.sameReview(r.draft,r.confirmed_version)?'此版本已明确确认':'此草稿未确认'}</span><label>实际作答支持（与合理性分开）<select data-space-support="${esc(r.region_id)}"><option value="not_assessed">待核查，不自动分配支持</option><option value="user_reports_observed">用户观察：有作答支持</option><option value="user_reports_not_observed">用户观察：尚未看到作答支持</option></select></label></div>`).join('');$('#newEmptySpace').onclick=newEmptyRegion;$('#spaceManager').querySelectorAll('[data-space-visible]').forEach(el=>el.onchange=()=>{setRegionMeta(el.dataset.spaceVisible,'visible',el.checked);save();render()});$('#spaceManager').querySelectorAll('[data-space-edit]').forEach(el=>el.onclick=()=>{switchRegion(el.dataset.spaceEdit);if(!draft().polygon.length)setMode('rectangle');render()});$('#spaceManager').querySelectorAll('[data-space-support]').forEach(el=>{const r=list.find(r=>r.region_id===el.dataset.spaceSupport);el.value=r.observation_support.status;el.onchange=()=>{setRegionMeta(r.region_id,'observation_support',{status:el.value,source:el.value==='not_assessed'?'not_assessed':'user_statement',record_ids:[],note:''});save();render()}});}
function newEmptyRegion(){if(pending()){toast('请先应用或取消预览');return false}const list=allRegions();if(list.length>=50){toast('每图最多50个空间');return false}const id=nextRegionId(list);regionBundle().alternatives.push({region_id:id,name:'新空间（空草稿）',draft:S.emptyFresh(),confirmed_version:null,visible:true,observation_support:S.support(null,cur())});switchRegion(id);setMode('rectangle');save();render();return true;}
function validateRecheck(value){if(!value||value.case_id!=='T30'||!['reference_pending','ready_for_rereview','reviewed','uncertain'].includes(value.status)||!['','matches_selected','none_match_confirmed','uncertain'].includes(value.verdict)||!Array.isArray(value.matching_region_ids)||new Set(value.matching_region_ids).size!==value.matching_region_ids.length||value.matching_region_ids.some(id=>typeof id!=='string'||!/^primary$|^space_[bcd]$|^space-\d+$/.test(id))||typeof value.reason!=='string'||value.reason.length>2000||!['','低','中','高'].includes(value.confidence)||value.source!=='new_independent_rereview'||value.original_history_overwritten!==false)throw Error('T30独立复审状态无效');return clone(value);}
function acceptedFloor(r){return G.valid(r.draft.polygon)&&(S.regionStatus(r)==='confirmed'||r.region_id==='primary'&&!r.draft.operations.length&&samePoly(r.draft.polygon,gt()));}
function renderRecheck(){const rows=allRegions(),accepted=rows.filter(acceptedFloor),ready=rows.filter(r=>['primary','space_b','space_c','space_d'].includes(r.region_id)).every(acceptedFloor);$('#recheckStatus').textContent='T30独立复审：'+({reference_pending:'参考待补充',ready_for_rereview:'已补参考，待复审',reviewed:'已人工复审',uncertain:'仍无法判断'}[recheckState.status]);$('#recheckPreparation').textContent=ready?'四个当前底面可供后续全图复算；本页未重算分数。导出后由主线程检查。':'全图复算尚未准备：四空间中仍有空草稿/未经明确确认的修改；本页未重算任何分数。';$('#recheckTargets').innerHTML=rows.map(r=>`<option value="${esc(r.region_id)}" ${acceptedFloor(r)?'':'disabled'} ${recheckState.matching_region_ids.includes(r.region_id)?'selected':''}>${esc(r.name)}${acceptedFloor(r)?'':'（空/待确认）'}</option>`).join('');if(document.activeElement!==$('#recheckReason'))$('#recheckReason').value=recheckState.reason;$('#recheckState').value=recheckState.status;$('#recheckVerdict').value=recheckState.verdict;$('#recheckConfidence').value=recheckState.confidence;}
$('#saveRecheck').onclick=()=>{try{const targets=[...$('#recheckTargets').selectedOptions].map(o=>o.value),v=validateRecheck({case_id:'T30',status:$('#recheckState').value,verdict:$('#recheckVerdict').value,matching_region_ids:targets,reason:$('#recheckReason').value,confidence:$('#recheckConfidence').value,source:'new_independent_rereview',original_history_overwritten:false});if(v.status==='ready_for_rereview'&&!allRegions().some(r=>['space_c','space_d'].includes(r.region_id)&&acceptedFloor(r)))throw Error('先补画并确认至少一个新增底面');if(v.verdict==='matches_selected'&&(!targets.length||targets.some(id=>!acceptedFloor(allRegions().find(r=>r.region_id===id)))))throw Error('匹配须选择已确认的底面');if(v.verdict==='none_match_confirmed'&&!allRegions().filter(r=>['primary','space_b','space_c','space_d'].includes(r.region_id)).every(acceptedFloor))throw Error('C/D未齐，不可声称四空间都不匹配');if(v.status==='reviewed'&&!v.verdict)throw Error('人工复审需填写判断');recheckState=v;save();renderRecheck();toast('独立复审已保存；原30份回执和T30原判断未覆盖')}catch(e){toast(e.message)}};

function validateRecheckAgainst(v,rows){const ok=r=>r&&G.valid(r.draft.polygon)&&(S.regionStatus(r)==='confirmed'||r.region_id==='primary'&&!r.draft.operations.length&&samePoly(r.draft.polygon,gt()));if(v.matching_region_ids.some(id=>!ok(rows.find(r=>r.region_id===id))))throw Error('独立复审只能指向有效已确认底面');if(v.verdict==='matches_selected'&&!v.matching_region_ids.length)throw Error('匹配判断缺少目标');if(v.verdict==='none_match_confirmed'&&!['primary','space_b','space_c','space_d'].every(id=>ok(rows.find(r=>r.region_id===id))))throw Error('四空间未齐，不可声称都不匹配');if(v.status==='ready_for_rereview'&&!rows.some(r=>['space_c','space_d'].includes(r.region_id)&&ok(r)))throw Error('新增参考尚未确认');if(v.status==='reviewed'&&!v.verdict)throw Error('已复审必须有判断');return v;}

function invalidateChangedReference(){if(!data||!spaceRegions[cur().image_code]||recheckState.status==='reference_pending')return;try{validateRecheckAgainst(recheckState,allRegions())}catch(e){const key='T30_rereview_before_reference_change_'+new Date().toISOString();unrecoveredDrafts[key]={rereview:clone(recheckState),reason:e.message,source:'previous_manual_rereview_kept_when_reference_changed'};recheckState={case_id:'T30',status:'reference_pending',verdict:'',matching_region_ids:[],reason:'',confidence:'',source:'new_independent_rereview',original_history_overwritten:false};toast('参考已修改：旧独立复核已保留在导出副本中，当前回到参考待补充；原30份回答不变');}}
